(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20+Math.cos(y*0.012-t*0.15)*15;
  const w1y = Math.cos(y*0.015-t*0.18)*20+Math.sin(x*0.013+t*0.22)*15;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025+t*0.4)*8+Math.cos(sy*0.02-t*0.3)*6;
  const w2y = Math.cos(sy*0.025-t*0.35)*8+Math.sin(sx*0.022+t*0.45)*6;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.9],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.8],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,1.2],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.7],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,1.0],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.85],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*40,0.085,1.8,1.15],
    [200+Math.sin(t*0.25+6)*110,220+Math.cos(t*0.45+3)*60,0.075,2.4,0.95]
  ];
  let aS=0,iS=0,dS=0,tW=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w; iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    dS+=Math.sin(d*f*1.3-t*sp*0.4+2.8)*w; tW+=w;
  }
  const act=aS/tW,inh=iS/tW,dif=dS/tW;
  const bg1=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2;
  const bg2=(Math.sin((fx+fy)*0.08+t*1.8)+Math.sin((fx-fy)*0.07-t*1.5))/2;
  const bg3=Math.sin(fx*0.12+fy*0.1+t*2.5)*0.3+Math.sin(fx*0.09-fy*0.11-t*2.2)*0.3;
  const bg=bg1*0.5+bg2*0.3+bg3*0.2;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const radial=Math.sin(dist*0.03-t*0.8)*0.3;
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const moire=Math.sin(fx*0.2)*Math.sin(fy*0.2)*Math.sin((fx-fy)*0.15+t*0.5)*0.2;
  const lap=(Math.sin(fx*0.08+t*0.5)*Math.cos(fy*0.08-t*0.3)+Math.sin((fx+fy)*0.06-t*0.7)*Math.cos((fx-fy)*0.05+t*0.6))*0.5;
  const react=Math.tanh((act-inh*0.7+dif*0.3+bg*0.3+spiral+radial+moire)*2.0);
  const refined=Math.tanh(react*1.5+lap*0.4);
  const blend=refined*0.7+cell*0.2+moire*0.1,v=blend*0.5+0.5;
  const pal=[[5,10,45],[12,45,90],[18,85,120],[25,140,130],[80,170,110],[180,190,70],[220,170,50],[210,120,60],[185,65,65],[140,35,80],[90,20,70],[40,15,60],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const inten=Math.abs(refined),lum=0.75+inten*0.25+Math.sin(react*Math.PI)*0.1;
  const edge=Math.abs(refined)>0.65?1.2:(Math.abs(refined)>0.4?1.05:0.95);
  const hs=Math.sin(ang*2+t*0.3)*0.05;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+hs*20))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+hs*10))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge-hs*15))|0
  ];
}
